from taf.internal.gnb.oam.coam.vdu.client.bb.v1 import (
    ApiClient,
    Configuration,
    GnssResetRequest,
    VduWebemApi,
    ApiException
)

from taf.gnb.oam.coam.vdu.services.bb_config.http_client import BBv1HttpClient
from taf.gnb.oam.coam.vdu.utilities.logger import log_request_response
from taf.gnb.oam.coam.vdu.utilities.poll_status import poll_status
from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1


@auto_token_refresh(api_exception=ApiException)
class BBConfigV1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        conf = Configuration()
        conf.verify_ssl = False
        conf.host = con_details.get_api_client_configuration(original_endpoint=conf.host)
        self.configuration = conf

        api_client = ApiClient(configuration=conf)
        api_client.request = log_request_response(api_client.request)

        self.vdu_webem_api = VduWebemApi(api_client=api_client)
        self.local_client = BBv1HttpClient(base_url=con_details.base_url,
                                           connection_alias=con_details.alias)

    def reset_rannic(self, rannic_r_dn, graceful_cell_shutdown=False, timeout=30):
        return self.local_client.reset_rannic(rannic_r_dn=rannic_r_dn, graceful_cell_shutdown=graceful_cell_shutdown,
                                              timeout=timeout)

    def get_rnic_reset_operation(self, operation_id, timeout=30):
        return self.local_client.get_reset_rannic_operation_status(operation_id=operation_id, timeout=timeout)

    def delete_rnic_reset_operation(self, operation_id, timeout=30):
        self.local_client.delete_reset_rannic_operation(operation_id=operation_id, timeout=timeout)

    def reset_gnss(self, gnsse_r_dn, timeout=30):
        gnss_reset_request = GnssResetRequest(gnsse_r_dn)
        return self.vdu_webem_api.gnss_operations_reset_post(gnss_reset_request=gnss_reset_request,
                                                             _request_timeout=timeout)

    def get_gnss_reset_operation_status(self, operation_id, timeout=30):
        return self.vdu_webem_api.gnss_operations_reset_operation_id_get(operation_id=operation_id,
                                                                         _request_timeout=timeout)

    def delete_gnss_reset_operation(self, operation_id, timeout=30):
        return self.vdu_webem_api.gnss_operations_reset_operation_id_delete(operation_id=operation_id,
                                                                            _request_timeout=timeout)

    def get_rnic_sync_status(self, rnic_runtime_distname, timeout=30):
        return self.local_client.get_rnic_sync_status(rnic_runtime_distname=rnic_runtime_distname, timeout=timeout)

    def configure_rannic_test_clock(self, rannic_r_dn, intended_test_clock_output=None, intended_frame_clock_output=None,
                                    timeout=30):
        response = self.local_client.post_rannic_test_clock_configure(rannic_r_dn=rannic_r_dn,
                                                                      intended_test_clock_output=intended_test_clock_output,
                                                                      intended_frame_clock_output=intended_frame_clock_output,
                                                                      timeout=timeout)
        operation_info = poll_status(instance=self.local_client, method_name="get_rannic_test_clock_operation_status",
                                     operation_id=response['id'], timeout=timeout, teardown_method_name="delete_rannic_test_clock_operation")
        return operation_info

    def get_rannic_test_clocks_status(self, timeout=30):
        return self.local_client.get_rannic_test_clocks_status(timeout=timeout)
